import{j as e}from"./vendor-motion-D-QS5Tde.js";import{H as o}from"./index-DTryBJkQ.js";import{N as r,F as i}from"./Footer-KawF-dDP.js";import{P as d,C as t,N as l}from"./NextProject-BUYY37sz.js";import{P as c}from"./ProjectOverview-DL46-v3B.js";import{C as a}from"./CsSection-D4zIf1tb.js";import{C as s}from"./CsFeatureGrid-BbPEq4n9.js";import{C as h}from"./CsSteps-CBcAYOuP.js";import{C as g}from"./CsPullquote-COh6crXd.js";import{C as n}from"./CsCallout-C4nnLEHM.js";import{C as u}from"./CsInfoGrid-CzxmBCtY.js";import{C as m}from"./CsCredits-DAUbZekd.js";import{C as p}from"./CsNumList-Dk-YZZ5D.js";import{C as f}from"./CsThanks-Cx9c-DN_.js";import{B as b}from"./BottomNav-BQIsGLMm.js";import"./vendor-react-P2F7fkol.js";import"./vendor-three-CMud_36L.js";function N(){return e.jsxs(e.Fragment,{children:[e.jsxs(o,{children:[e.jsx("title",{children:"OrgDashboard · Parth Pawar"}),e.jsx("meta",{name:"description",content:"OrgDashboard — Designing the SaaS platform that gives AI agents organizational context. Knowledge base, integrations dashboard, and action approval system. Case study by Parth Pawar."}),e.jsx("meta",{property:"og:type",content:"article"}),e.jsx("meta",{property:"og:title",content:"OrgDashboard · Parth Pawar"}),e.jsx("meta",{property:"og:description",content:"SaaS platform that gives AI agents a brain for your company — designing for two users simultaneously."}),e.jsx("meta",{property:"og:image",content:"https://parthpawar.com/Assets/images/org-dashboard.png"})]}),e.jsx(r,{}),e.jsxs("main",{id:"main-content",className:"project-main",style:{"--project-color":"#2D3748"},children:[e.jsx(d,{backLink:"/work",categorySlug:"ux-design",backLabel:"Back to Work",tags:["SaaS","AI","Product Design","B2B"],title:"OrgDashboard",subtitle:"Designing the SaaS platform that gives AI agents organizational context — a shared brain for every agent in your company",info:[{label:"Role",value:"Designer"},{label:"Type",value:"SaaS · Developer Tools"},{label:"Platform",value:"Web, CLI, MCP"},{label:"Stack",value:"React, Tailwind, shadcn/ui"},{label:"Year",value:"2026"}],heroImage:"/Assets/images/org-dashboard.png",heroAlt:"OrgDashboard — SaaS platform giving AI agents organizational context"}),e.jsx(c,{id:"cs-problem",sections:[{label:"The Problem",content:"AI agents today are powerful but amnesiac. Every session starts from zero. Engineers paste context into prompts, maintain private files of API keys, and manually explain their company to Claude over and over. What one person’s agent learns never benefits anyone else on the team. Ten engineers means ten separate, incomplete mental models of the company."},{label:"The Solution",content:"OrgDashboard is the infrastructure layer between a company’s data and its AI agents. Connect your tools, and every agent in your organization immediately gains access to a shared brain — SOPs, project status, team structure, KPIs, and institutional knowledge that compounds over time."}]}),e.jsxs(a,{id:"cs-concept",label:"Concept",title:"Give Your AI Agents a Brain for Your Company",children:[e.jsxs(t,{children:[e.jsx("p",{children:"The root cause is simple: there is no shared infrastructure layer between a company’s data and its AI agents. Every agent session is a blank slate. Engineers waste cycles rediscovering information. Knowledge stays siloed. Without persistent context, agents can only handle simple, self-contained tasks — they cannot manage ongoing workflows or make decisions informed by cross-functional data."}),e.jsx("p",{children:"OrgDashboard solves this by creating a persistent, shared knowledge layer. Companies connect their existing tools — Slack, Linear, QuickBooks, GitHub, PostHog, Google Workspace — and agents gain organizational awareness through a CLI and MCP server that plugs into any existing harness."})]}),e.jsx(n,{children:e.jsx("p",{children:"“The OrgDashboard CLI is not a standalone agent — it is an extension to any existing agent harness. When added as an MCP server to Claude Code, Zed, or Cursor, the agent gains organizational awareness without replacing any of the harness’s existing tools.”"})}),e.jsx("div",{className:"cs-slide reveal",children:e.jsx("img",{src:"/Assets/images/org-dashboard.png",alt:"Dashboard overview",loading:"lazy",style:{borderRadius:"8px",border:"1px solid rgba(255,255,255,0.1)",width:"100%",height:"auto"}})}),e.jsx("p",{className:"cs-caption",children:"Dashboard overview — the human-facing home screen showing connected integrations, knowledge base health, and pending agent actions"})]}),e.jsxs(a,{id:"cs-two-users",label:"The Design Challenge",title:"One Platform, Two Fundamentally Different Users",children:[e.jsx(t,{children:e.jsx("p",{children:"The core design challenge was unprecedented: design a single platform that serves two users simultaneously — AI agents and humans — with completely different interaction models, needs, and capabilities. Agents operate through structured APIs and CLIs. Humans need visual dashboards and approval interfaces. Both need to read and write to the same knowledge base without stepping on each other."})}),e.jsx(g,{quote:"If an agent can find it through org kb search, a human should be able to find it through the same logical path in the UI. One data model, two interaction paradigms.",cite:"— Design principle, OrgDashboard"}),e.jsx(s,{features:[{title:"AI Agents",desc:"Operate through CLI commands and MCP tools. Need structured data retrieval, granular KB edits, and a clear action proposal system. Interact programmatically — every surface must be machine-parseable."},{title:"Humans",desc:"Manage, monitor, and approve through the web dashboard. Need visual knowledge exploration, connection management, action queues, and synthesized views of what agents are doing across the org."},{title:"Shared Knowledge Base",desc:"Both users read from and write to the same persistent store. The design had to ensure agents could build knowledge incrementally while humans could browse, verify, and correct it visually."},{title:"Trust Boundary",desc:"Not all agent actions are safe to auto-approve. The action system needed clear tiers: KB writes are free, but external actions (Slack messages, ticket creation, purchases) require human approval."}]})]}),e.jsxs(a,{id:"cs-decisions",label:"Design Decisions",title:"Three Bets That Shaped the Product",children:[e.jsx("h3",{className:"cs-section-subtitle",children:"1. Grayscale-First Visual Language"}),e.jsxs(t,{children:[e.jsxs("p",{children:["For a developer-facing SaaS product, visual noise is the enemy. I designed a grayscale-first color system where the only source of color comes from the warm ",e.jsx("code",{children:"#fafafa"})," background and intentional status indicators. No decorative color, no branded gradients. The palette uses ",e.jsx("code",{children:"rgba()"})," opacity values for consistent tonal relationships — inspired by Linear, Vercel, and Stripe’s design sensibilities."]}),e.jsx("p",{children:"This restraint serves a purpose: when color does appear (a red destructive badge, a green active status), it carries real meaning. Developers notice it because the rest of the interface is deliberately quiet."})]}),e.jsx("h3",{className:"cs-section-subtitle",children:"2. Agent-First Information Architecture"}),e.jsxs(t,{children:[e.jsx("p",{children:"Most dashboards are designed for humans and then retrofitted with APIs. I inverted this. The information architecture was designed for agent consumption first — structured, queryable, composable — and the human dashboard was built as a visual projection of that same data model."}),e.jsxs("p",{children:["The knowledge base uses an agentic retrieval model, not pure RAG. Agents browse by type or tag, follow relationships, and explore iteratively. The web dashboard’s knowledge explorer mirrors this exact navigation model — if an agent can find something via ",e.jsx("code",{children:"org kb search"}),", a human can find it through the same logical path in the UI."]})]}),e.jsx("h3",{className:"cs-section-subtitle",children:"3. Progressive Trust Through Action Tiers"}),e.jsxs(t,{children:[e.jsx("p",{children:"The action system was the most critical trust design. Reading data is free — agents should never hesitate to gather context. Writing to the knowledge base is auto-approved — building shared knowledge should be frictionless. But external actions — sending emails, posting to Slack, creating tickets, making purchases — enter an approval queue."}),e.jsx("p",{children:"The approval interface had to be fast enough that humans don’t become bottlenecks, but informative enough that they can make confident decisions. Each pending action shows the full context: what the agent wants to do, why it proposed it, and what data it used to make the decision."})]}),e.jsx(n,{children:e.jsxs("p",{children:[e.jsx("strong",{children:"Design principle:"})," The trust boundary lives at the point of external side effects. Internal knowledge building is always safe. External writes require human judgment. This distinction is baked into every surface — from the CLI’s command structure to the dashboard’s approval queue."]})})]}),e.jsxs(a,{id:"cs-system",label:"Design System",title:"Built for Developer Trust",children:[e.jsx(t,{style:{marginBottom:"2rem"},children:e.jsx("p",{children:"The design system was built from scratch for a developer-facing SaaS product. Three font families, each with a distinct purpose. A grayscale-first color system. Components that prioritize clarity over personality."})}),e.jsx(u,{items:[{key:"Heading",value:"Newsreader"},{key:"Body",value:"DM Sans"},{key:"Mono",value:"DM Mono"},{key:"Background",value:"#fafafa"},{key:"Foreground",value:"#1c2024"},{key:"Framework",value:"Tailwind + shadcn/ui"}]}),e.jsx(s,{features:[{title:"Minimal, Refined Components",desc:"Cards with no default shadow. Badges that are pill-shaped and subtle, never bold. Destructive actions use outlined/tinted treatment — not solid red buttons. Every component earns trust through restraint."},{title:"Opacity-Based Color Scale",desc:"Instead of named gray tokens, the system uses rgba(0,0,0,X) at consistent opacity stops. This creates natural tonal relationships and ensures every text shade has a clear purpose — from labels at 0.35 to body text at 0.55."},{title:"Quiet Confidence",desc:"No box shadows by default. Hover states add micro-shadows. Transitions at 0.15s — never bouncy or elastic. The interface feels precise, not playful. Developers trust tools that behave predictably."},{title:"Anti-Patterns",desc:"Explicitly documented what we don’t do: no dark code blocks, no solid destructive buttons, no heavy box shadows, no saturated status colors, no font-weight 700 except specific emphasis. Taste is as much about what you exclude."}]})]}),e.jsxs(a,{id:"cs-surfaces",label:"Product Surfaces",title:"Four Surfaces, One Coherent Experience",children:[e.jsx(t,{style:{marginBottom:"2rem"},children:e.jsx("p",{children:"OrgDashboard lives across four distinct surfaces. Each was designed for its specific context while sharing a unified data model and design language."})}),e.jsx(h,{steps:[{num:"1",title:"Web Dashboard",desc:"The human-facing interface. React SPA with Clerk auth, connection management via Composio, knowledge explorer, action approval queue, and synthesized org dashboards. Sidebar navigation with seamless org switching."},{num:"2",title:"CLI",desc:"The org command that agents use to interact with the platform. Granular KB operations (search, create, update, append, replace), data reading from connected sources, and action proposals. Published to npm."},{num:"3",title:"MCP Server",desc:"Maps 1:1 to CLI commands. When added to Claude Code, Zed, or Cursor, the agent gains all OrgDashboard capabilities as native MCP tools. Zero configuration beyond the API key."},{num:"4",title:"Knowledge Base",desc:"The shared brain. MongoDB-backed, schema-flexible. Stores entities, SOPs, skills, context, and agent-discovered insights. All writes are versioned with full edit history and rollback capability."}]})]}),e.jsxs(a,{id:"cs-results",label:"Results",title:"Measuring Success Honestly",children:[e.jsx(t,{children:e.jsx("p",{children:"OrgDashboard is an early-stage product, so traditional business metrics like revenue or DAU don’t tell the full story yet. Instead, we focused on design quality indicators — signals that the product is solving the right problem in the right way."})}),e.jsx(s,{features:[{title:"Task Completion Rate",desc:"In moderated usability tests, 8 out of 10 engineers completed core workflows — connecting an integration, searching the KB, and approving an agent action — without guidance on their first session."},{title:"Time to First Value",desc:"From sign-up to a working agent query with real organizational context averaged under 6 minutes in internal testing. The onboarding flow was designed to get one integration connected and one KB entry created immediately."},{title:"Approval Queue Speed",desc:"The action approval interface was tested for decision confidence. Users reported feeling confident in approve/reject decisions within 5–8 seconds per action, validating that the context-first card design works."},{title:"What We Haven’t Measured Yet",desc:"Long-term knowledge compounding, cross-team context reuse, and whether the shared brain model actually reduces repeated context-pasting at scale. These are the metrics that will matter most — and the ones that need real production usage to validate."}]})]}),e.jsx(a,{id:"cs-reflections",label:"Reflections",title:"What Designing for Agents Taught Me",children:e.jsx(p,{items:[e.jsxs(e.Fragment,{children:[e.jsx("strong",{children:"Agents are a user, not a feature."})," Designing for agents requires the same empathy and rigor as designing for humans. They have workflows, frustrations, and failure modes. The CLI’s command structure went through as many iterations as any UI component."]}),e.jsxs(e.Fragment,{children:[e.jsx("strong",{children:"Trust is earned through transparency."})," The action approval system works because agents explain their reasoning. Every pending action includes context — not just what, but why. Humans approve faster when they understand the agent’s decision-making."]}),e.jsxs(e.Fragment,{children:[e.jsx("strong",{children:"Grayscale is not boring — it’s confident."})," Stripping away decorative color forced every design decision to earn its place through typography, spacing, and hierarchy alone. When the fundamentals are strong, you don’t need color as a crutch."]}),e.jsxs(e.Fragment,{children:[e.jsx("strong",{children:"Design the data model, then the interface."})," Starting with the agent’s data needs and working backward to the human dashboard produced a more coherent product than the reverse would have. The UI is a projection of the API — and that alignment shows."]})]})}),e.jsxs(a,{label:"Credits",title:"Team",children:[e.jsx(m,{credits:[{role:"Designer",name:"Parth Pawar"},{role:"Scope",name:"Product Design, Design System, Frontend"},{role:"Stack",name:"React 19, Tailwind, shadcn/ui, Clerk, Composio"},{role:"Backend",name:"Bun, Hono, MongoDB, MCP SDK"}]}),e.jsx(f,{contactCta:!0,style:{marginTop:"4rem"}})]}),e.jsx(b,{sections:[{id:"cs-problem",label:"The Problem"},{id:"cs-concept",label:"Concept"},{id:"cs-two-users",label:"Two Users"},{id:"cs-decisions",label:"Design Decisions"},{id:"cs-system",label:"Design System"},{id:"cs-surfaces",label:"Product Surfaces"},{id:"cs-results",label:"Results"},{id:"cs-reflections",label:"Reflections"}]})]}),e.jsx(l,{slug:"raahi-project",title:"Raahi",image:"/Assets/images/raahi.jpg"}),e.jsx(i,{})]})}export{N as default};
